import{_ as d,o as a,c as e,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"前端设计模式全景","description":"","frontmatter":{"title":"前端设计模式全景","outline":[2,3]},"headers":[],"relativePath":"frontend/topics/design-patterns/index.md","filePath":"frontend/topics/design-patterns/index.md","lastUpdated":1785589115000}'),o={name:"frontend/topics/design-patterns/index.md"};function l(h,t,i,n,s,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="前端设计模式全景" tabindex="-1">前端设计模式全景 <a class="header-anchor" href="#前端设计模式全景" aria-label="Permalink to &quot;前端设计模式全景&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>设计模式不是必须套用的类结构，也不是资深程度的证明。它是对一类重复协作问题的命名：哪些职责应当稳定，哪里允许变化，对象如何创建、组合、通信和释放。前端真正需要掌握的是识别这些关系，并在直接函数、普通对象和模式化结构之间选择成本最低的方案。</p><p>本分组只讨论代码级模式。模块分层、微前端、完整插件平台和组织治理属于工程体系；这里关注一个模块或一条交互链内部的对象协作，并用框架无关的 TypeScript 展示入口、实现、调用和结果。</p><h2 id="_1-知识地图" tabindex="-1">1. 知识地图 <a class="header-anchor" href="#_1-知识地图" aria-label="Permalink to &quot;1. 知识地图&quot;">​</a></h2><h3 id="_1-1-模式解决的四类变化" tabindex="-1">1.1 模式解决的四类变化 <a class="header-anchor" href="#_1-1-模式解决的四类变化" aria-label="Permalink to &quot;1.1 模式解决的四类变化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变化类型</th><th>核心问题</th><th>代表模式</th></tr></thead><tbody><tr><td>创建变化</td><td>调用方不应依赖具体构造过程</td><td>工厂、构建器、依赖注入</td></tr><tr><td>结构变化</td><td>现有对象怎样适配、增强或控制访问</td><td>适配器、装饰器、代理</td></tr><tr><td>行为变化</td><td>算法、请求或阶段行为怎样替换</td><td>策略、命令、状态</td></tr><tr><td>协作变化</td><td>多个参与者怎样传播、拦截和组合行为</td><td>观察者、事件总线、响应式、责任链、中间件、插件</td></tr></tbody></table><p>组件组合和异步交互横跨行为与协作两类问题：前者处理视图能力如何拼装，后者处理请求期间状态、竞态和取消如何建模。</p><h3 id="_1-2-阅读模式时固定回答的问题" tabindex="-1">1.2 阅读模式时固定回答的问题 <a class="header-anchor" href="#_1-2-阅读模式时固定回答的问题" aria-label="Permalink to &quot;1.2 阅读模式时固定回答的问题&quot;">​</a></h3><ol><li><strong>变化点是什么</strong>：算法、依赖、外部接口、状态阶段，还是订阅关系；</li><li><strong>参与者是谁</strong>：谁发起调用，谁拥有状态，谁决定下一步，谁负责清理；</li><li><strong>协作契约是什么</strong>：函数签名、接口、事件载荷或上下文对象；</li><li><strong>控制流是否可见</strong>：能否从入口追踪到最终结果和副作用；</li><li><strong>引入成本是什么</strong>：新增间接层、对象数量、顺序依赖、调试难度和资源生命周期。</li></ol><p>若无法回答这些问题，就还没有理由引入模式。</p><h2 id="_2-文章索引" tabindex="-1">2. 文章索引 <a class="header-anchor" href="#_2-文章索引" aria-label="Permalink to &quot;2. 文章索引&quot;">​</a></h2><h3 id="_2-1-选择与边界" tabindex="-1">2.1 选择与边界 <a class="header-anchor" href="#_2-1-选择与边界" aria-label="Permalink to &quot;2.1 选择与边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>核心问题</th><th>重点</th></tr></thead><tbody><tr><td><a href="/frontend/topics/design-patterns/principles-boundaries">模式选择与代码边界</a></td><td>什么时候值得引入模式</td><td>变化点、协作契约、所有权、最小抽象与验证</td></tr><tr><td><a href="/frontend/topics/design-patterns/anti-patterns-refactoring">反模式与代码级重构</a></td><td>怎样识别抽象已经妨碍修改</td><td>症状、根因、保行为重构与回归验证</td></tr></tbody></table><h3 id="_2-2-创建、结构与行为" tabindex="-1">2.2 创建、结构与行为 <a class="header-anchor" href="#_2-2-创建、结构与行为" aria-label="Permalink to &quot;2.2 创建、结构与行为&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>核心问题</th><th>重点</th></tr></thead><tbody><tr><td><a href="/frontend/topics/design-patterns/creational">工厂、构建器与依赖注入</a></td><td>谁知道具体类型、构造步骤和依赖</td><td>创建决策、分步构造、对象生命周期</td></tr><tr><td><a href="/frontend/topics/design-patterns/structural">适配器、装饰器与代理</a></td><td>怎样复用、增强或限制现有对象</td><td>接口转换、同接口包装、访问控制</td></tr><tr><td><a href="/frontend/topics/design-patterns/behavioral">策略、命令与状态模式</a></td><td>行为怎样替换、保存或随阶段切换</td><td>调用者选择、请求对象化、状态迁移</td></tr></tbody></table><h3 id="_2-3-前端协作模式" tabindex="-1">2.3 前端协作模式 <a class="header-anchor" href="#_2-3-前端协作模式" aria-label="Permalink to &quot;2.3 前端协作模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>核心问题</th><th>重点</th></tr></thead><tbody><tr><td><a href="/frontend/topics/design-patterns/events-reactivity">观察者、事件总线与响应式模式</a></td><td>变化怎样传播给多个消费者</td><td>订阅归属、事件路由、依赖传播与释放</td></tr><tr><td><a href="/frontend/topics/design-patterns/components-state-async">组件组合与异步交互模式</a></td><td>UI 行为怎样脱离具体视图和框架生命周期</td><td>Headless Controller、Presenter / ViewModel、Adapter 与释放</td></tr><tr><td><a href="/frontend/topics/design-patterns/plugins-dependency-injection">责任链、中间件与插件组合</a></td><td>多段处理逻辑怎样按序组合</td><td>短路、洋葱调用、安装期扩展与清理</td></tr></tbody></table><h3 id="_2-4-未单列模式与归属" tabindex="-1">2.4 未单列模式与归属 <a class="header-anchor" href="#_2-4-未单列模式与归属" aria-label="Permalink to &quot;2.4 未单列模式与归属&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>本手册中的归属</th><th>不单列原因</th></tr></thead><tbody><tr><td>Facade（外观）</td><td>模式选择与代码边界、结构型模式</td><td>前端中通常就是模块公开的窄入口；只有出现真实子系统边界时才需要命名，不必为普通导出函数套模式</td></tr><tr><td>Composite（组合）</td><td>组件组合、树与遍历、场景树</td><td>DOM、组件树和图形 Container 已体现统一处理叶子与容器；遍历算法与具体框架生命周期分别在对应问题域展开</td></tr><tr><td>Template Method（模板方法）</td><td>策略与中间件</td><td>前端更常用函数组合、策略注入或中间件表达固定骨架与可变步骤，避免为了复用流程强制继承</td></tr><tr><td>Flyweight（享元）</td><td>图形渲染性能、缓存与资源共享</td><td>纹理、Geometry 和不可变配置共享必须结合资源所有权与性能数据讨论，脱离场景单讲类图价值有限</td></tr></tbody></table><p>这里不是宣布这些模式“不重要”，而是避免按 GoF 名单重复建章。遇到真实问题时先进入右侧问题域，再判断是否需要使用该名称解释协作关系。</p><h2 id="_3-容易混淆的模式" tabindex="-1">3. 容易混淆的模式 <a class="header-anchor" href="#_3-容易混淆的模式" aria-label="Permalink to &quot;3. 容易混淆的模式&quot;">​</a></h2><h3 id="_3-1-观察者、事件总线与响应式" tabindex="-1">3.1 观察者、事件总线与响应式 <a class="header-anchor" href="#_3-1-观察者、事件总线与响应式" aria-label="Permalink to &quot;3.1 观察者、事件总线与响应式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>观察者</th><th>事件总线</th><th>响应式</th></tr></thead><tbody><tr><td>订阅对象</td><td>一个明确的数据源</td><td>总线上的事件主题</td><td>值及其依赖关系</td></tr><tr><td>发布者是否认识通道</td><td>认识自己的订阅集合</td><td>只认识事件名与总线</td><td>通常只写入源值</td></tr><tr><td>主要用途</td><td>对象状态变化通知</td><td>跨模块事实广播</td><td>派生值和副作用自动更新</td></tr><tr><td>主要风险</td><td>忘记取消订阅</td><td>控制流隐藏、事件名漂移</td><td>隐式依赖、重复计算和泄漏</td></tr></tbody></table><h3 id="_3-2-策略、命令与状态" tabindex="-1">3.2 策略、命令与状态 <a class="header-anchor" href="#_3-2-策略、命令与状态" aria-label="Permalink to &quot;3.2 策略、命令与状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>策略</th><th>命令</th><th>状态</th></tr></thead><tbody><tr><td>被封装的内容</td><td>可替换算法</td><td>一次请求及其参数</td><td>当前阶段对应的行为</td></tr><tr><td>谁选择行为</td><td>调用方或上下文</td><td>创建命令的一方</td><td>状态机迁移规则</td></tr><tr><td>是否强调历史</td><td>否</td><td>常见于队列、日志、撤销</td><td>强调合法迁移</td></tr><tr><td>典型信号</td><td>多种算法同一输入输出</td><td>请求需要排队、记录或撤销</td><td>大量按阶段分支且阶段会变化</td></tr></tbody></table><h3 id="_3-3-责任链、中间件与插件" tabindex="-1">3.3 责任链、中间件与插件 <a class="header-anchor" href="#_3-3-责任链、中间件与插件" aria-label="Permalink to &quot;3.3 责任链、中间件与插件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>责任链</th><th>中间件</th><th>插件</th></tr></thead><tbody><tr><td>组合时机</td><td>处理请求前排列处理者</td><td>处理请求前组成管线</td><td>主机初始化或运行期安装</td></tr><tr><td>是否必须继续</td><td>找到处理者即可停止</td><td>由 <code>next()</code> 决定是否进入下游</td><td>由插件注册的扩展点决定</td></tr><tr><td>生命周期</td><td>通常跟随处理链</td><td>通常跟随一次请求</td><td>具有安装、运行和卸载生命周期</td></tr><tr><td>典型用途</td><td>首个匹配者处理</td><td>请求前后环绕逻辑</td><td>为主机贡献命令、钩子或能力</td></tr></tbody></table><h2 id="_4-选择顺序" tabindex="-1">4. 选择顺序 <a class="header-anchor" href="#_4-选择顺序" aria-label="Permalink to &quot;4. 选择顺序&quot;">​</a></h2><h3 id="_4-1-从直接代码开始" tabindex="-1">4.1 从直接代码开始 <a class="header-anchor" href="#_4-1-从直接代码开始" aria-label="Permalink to &quot;4.1 从直接代码开始&quot;">​</a></h3><p>按以下顺序增加抽象强度：</p><ol><li>单一实现且变化很少：普通函数或对象；</li><li>多处共享同一契约：提取命名函数与显式接口；</li><li>已出现至少两种真实变化：选择相应模式；</li><li>需要跨模块扩展、生命周期和治理：再进入架构或平台设计。</li></ol><p>模式通常应来自已经观察到的变化，而不是来自对未来的猜测。只有安全边界、外部协议隔离等高风险约束，才可能在第一个实现之前就值得建立适配层。</p><h3 id="_4-2-按问题信号定位文章" tabindex="-1">4.2 按问题信号定位文章 <a class="header-anchor" href="#_4-2-按问题信号定位文章" aria-label="Permalink to &quot;4.2 按问题信号定位文章&quot;">​</a></h3><table tabindex="0"><thead><tr><th>代码信号</th><th>先检查</th><th>不要立即假设</th></tr></thead><tbody><tr><td>到处出现 <code>new ConcreteType()</code></td><td>工厂或依赖注入</td><td>必须引入依赖注入容器</td></tr><tr><td>函数参数不断增加且存在组合约束</td><td>构建器</td><td>所有参数对象都需要构建器</td></tr><tr><td>外部 SDK 类型渗透业务代码</td><td>适配器</td><td>只做同名方法转发就足够</td></tr><tr><td>多层包装都保持同一接口</td><td>装饰器</td><td>包装层顺序没有影响</td></tr><tr><td>巨大的算法分支</td><td>策略或状态</td><td>所有 <code>switch</code> 都是坏代码</td></tr><tr><td>请求需要撤销、重放或排队</td><td>命令</td><td>普通回调也要建类</td></tr><tr><td>多个模块响应同一事实</td><td>观察者或事件总线</td><td>事件总线可以替代所有直接调用</td></tr><tr><td>多段逻辑包围一次处理</td><td>中间件</td><td>任意函数数组都是中间件</td></tr></tbody></table><h2 id="_5-推荐学习路径" tabindex="-1">5. 推荐学习路径 <a class="header-anchor" href="#_5-推荐学习路径" aria-label="Permalink to &quot;5. 推荐学习路径&quot;">​</a></h2><h3 id="_5-1-日常应用开发" tabindex="-1">5.1 日常应用开发 <a class="header-anchor" href="#_5-1-日常应用开发" aria-label="Permalink to &quot;5.1 日常应用开发&quot;">​</a></h3><ol><li>模式选择与代码边界；</li><li>策略、命令与状态；</li><li>观察者、事件总线与响应式；</li><li>组件组合与异步交互；</li><li>反模式与代码级重构。</li></ol><h3 id="_5-2-基础设施与工具开发" tabindex="-1">5.2 基础设施与工具开发 <a class="header-anchor" href="#_5-2-基础设施与工具开发" aria-label="Permalink to &quot;5.2 基础设施与工具开发&quot;">​</a></h3><p>在日常路线之后学习：</p><ol><li>工厂、构建器与依赖注入；</li><li>适配器、装饰器与代理；</li><li>责任链、中间件与插件组合。</li></ol><p>这条路线更关注第三方接口隔离、可替换依赖、处理管线和扩展点。</p><h2 id="_6-掌握与验证" tabindex="-1">6. 掌握与验证 <a class="header-anchor" href="#_6-掌握与验证" aria-label="Permalink to &quot;6. 掌握与验证&quot;">​</a></h2><h3 id="_6-1-代码验收" tabindex="-1">6.1 代码验收 <a class="header-anchor" href="#_6-1-代码验收" aria-label="Permalink to &quot;6.1 代码验收&quot;">​</a></h3><p>每次引入模式至少验证：</p><ul><li>使用者只依赖声明的契约，不读取具体实现内部状态；</li><li>两个真实变体可以互换，结果差异符合预期；</li><li>顺序、短路、重入和异常等关键协作规则有测试；</li><li>订阅、计时器、网络请求和插件都能显式释放；</li><li>从入口到副作用仍可追踪，没有依赖全局注册表或神秘字符串；</li><li>删除一个变体时，稳定代码不需要大面积修改。</li></ul><h3 id="_6-2-最终判断" tabindex="-1">6.2 最终判断 <a class="header-anchor" href="#_6-2-最终判断" aria-label="Permalink to &quot;6.2 最终判断&quot;">​</a></h3><p>能写出类图并不等于掌握模式。更可靠的标准是：能说明当前问题不用模式时有多简单，引入模式后消除了哪一种变化扩散，又增加了哪些间接成本；当这些成本不再值得时，也能把结构收回普通函数和对象。</p><h2 id="_7-参考资料" tabindex="-1">7. 参考资料 <a class="header-anchor" href="#_7-参考资料" aria-label="Permalink to &quot;7. 参考资料&quot;">​</a></h2><ul><li><a href="https://www.typescriptlang.org/docs/handbook/2/objects.html" target="_blank" rel="noreferrer">TypeScript Handbook：Interfaces</a></li><li><a href="https://www.typescriptlang.org/docs/handbook/2/classes.html" target="_blank" rel="noreferrer">TypeScript Handbook：Classes</a></li><li><a href="https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Proxy" target="_blank" rel="noreferrer">MDN：Proxy</a></li><li><a href="https://dom.spec.whatwg.org/#events" target="_blank" rel="noreferrer">WHATWG DOM：Events</a></li><li><a href="https://refactoring.com/catalog/" target="_blank" rel="noreferrer">Refactoring：Catalog</a></li></ul>',50)])])}const _=d(o,[["render",l]]);export{p as __pageData,_ as default};
